#include "DISPLAY_FOR_G.h"

// 初始化串口并设置为阻塞模式/常用参数
HANDLE OpenAndConfigureSerialPort(const wchar_t* portName, DWORD baudRate = CBR_115200)
{
    // 1. 打开串口：注意 COM25 必须写作 L"\\\\.\\COM25"
    HANDLE hSerial = CreateFileW(
                         portName,
                         GENERIC_READ | GENERIC_WRITE,
                         0,              // 串口不支持共享访问
                         NULL,           // 默认安全属性
                         OPEN_EXISTING,  // 必须打开已存在的串口
                         0,              // 同步 I/O 模式
                         NULL
                     );

    if (hSerial == INVALID_HANDLE_VALUE)
    {
        std::cerr << "无法打开串口, 错误代码: " << GetLastError() << std::endl;
        return INVALID_HANDLE_VALUE;
    }

    // 2. 配置 DCB（波特率、数据位、停止位、校验位）
    DCB dcbSerialParams = { 0 };
    dcbSerialParams.DCBlength = sizeof(dcbSerialParams);

    if (!GetCommState(hSerial, &dcbSerialParams))
    {
        std::cerr << "获取串口状态失败" << std::endl;
        CloseHandle(hSerial);
        return INVALID_HANDLE_VALUE;
    }

    dcbSerialParams.BaudRate = baudRate;
    dcbSerialParams.ByteSize = 8;
    dcbSerialParams.StopBits = ONESTOPBIT;
    dcbSerialParams.Parity   = NOPARITY;

    if (!SetCommState(hSerial, &dcbSerialParams))
    {
        std::cerr << "配置串口参数失败" << std::endl;
        CloseHandle(hSerial);
        return INVALID_HANDLE_VALUE;
    }

    // 3. 配置超时限制
    COMMTIMEOUTS timeouts = { 0 };
    timeouts.ReadIntervalTimeout         = 50;
    timeouts.ReadTotalTimeoutConstant    = 50;
    timeouts.ReadTotalTimeoutMultiplier  = 10;
    timeouts.WriteTotalTimeoutConstant   = 50;
    timeouts.WriteTotalTimeoutMultiplier = 10;

    SetCommTimeouts(hSerial, &timeouts);

    return hSerial;
}

// 将 stdout 重定向到指定串口
bool RedirectStdoutToSerial(HANDLE hSerial)
{
    if (hSerial == INVALID_HANDLE_VALUE)
        return false;

    // 1. 将 Win32 HANDLE 关联到 C 运行时的文件描述符 (C Runtime File Descriptor)
    int fd = _open_osfhandle(reinterpret_cast<intptr_t>(hSerial), _O_TEXT);
    if (fd == -1)
    {
        std::cerr << "关联 _open_osfhandle 失败" << std::endl;
        return false;
    }

    // 2. 使用 _dup2 将标准输出 (1) 重定向到串口的文件描述符 fd
    if (_dup2(fd, 1) != 0)
    {
        std::cerr << "重定向 _dup2 失败" << std::endl;
        return false;
    }

    // 3. 关闭缓冲，确保 printf 内容立刻被 Send 到串口，避免留在内存缓冲区
    setvbuf(stdout, NULL, _IONBF, 0);

    // （可选）若希望 C++ 的 std::cout 也生效，可同步取消 std::cin/cout 缓冲绑定
    std::ios::sync_with_stdio();

    return true;
}
